import json
s=json.load(open('system-spec/spec-state.json'))
print(s.keys())
print(json.dumps(s.get('hearing_progress')))
print(json.dumps({k:v for k,v in s['requirements_foundation'].items() if k=='effective_source_refs'},ensure_ascii=False))
ids={q['id'] for q in s['qa_log']}
for c,r in s['matrix'].items():
  for p,v in r.items():
    if v['state']=='確定':
      if v.get('qa_ref') not in ids: print('dangling',c,p)
      for q in v.get('qa_refs',[]):
        if q not in ids: print('dangling-support',c,p,q)
      print(c,p,v['qa_ref'],[ (q) for q in [v['qa_ref']]+v.get('qa_refs',[]) if 'superseded_by' in next(x for x in s['qa_log'] if x['id']==q)])
    elif v['state']!='対象外' : print('uncollected',c,p)
    else:
      if v.get('qa_ref') not in ids or v.get('approval_ref') not in {a['id'] for a in s['approval_log']}: print('bad oos',c,p)
print([q['id'] for q in s['qa_log'] if 'superseded_by' in q])
E
